import { handle, requireUser } from "@/lib/server/http";
import { getRuntime } from "@/lib/server/runtime";

export const dynamic = "force-dynamic";

/** Recent important alerts generated by the backend (in-app banner today, push later). */
export const GET = handle(async () => {
  await requireUser();
  const rt = await getRuntime();
  const snap = await rt.snapshot();
  const names = rt.names(snap);
  return {
    now: snap.now,
    notifications: rt.state.notifications
      .filter((n) => snap.now - n.at < 3 * 3_600_000)
      .slice(-10)
      .reverse()
      .map((n) => ({ id: n.id, at: n.at, level: n.level, title: n.title, body: n.body, fridge: names[n.fridgeId] ?? n.fridgeId, missionId: n.missionId })),
  };
});
